.courses-v26 {
    //Specific course-v26 styles to generic tags.
    h1 {
        @include media('>tablet') {
            font-size: $font-size--theta;
        }

        @include media('>desktop') {
            font-size: $measure--medium3;
        }
    }
    h2 {
        @include thetatype();
    }
}

.courses-v26__overview {
    .courses-v26__overview__heading {
        margin-bottom: $measure--small4;
        @include h2style();
        font-weight: $font-weight-book;
        text-align: center;

        @include media('<=mobile') {
            grid-column: wide-start / wide-end;
        }
    }

    .logo-block-v26 {
        margin-bottom: $measure--small4;
    }

    // overview - accredidation styles
    // .wrapper--logo {
    //     max-width: $max-line-length;
    // }

    .courses-v26__overview__content--2cols {
        display: flex;
        flex-direction: row;
        gap: $measure--small4;

        @include media('<between') {
            flex-direction: column;
        }

        > div {
            flex: 1;
        }
    }
}

.courses-v26__fees__course-info-cards {
    @include media('<small') {
        display: flex;
        flex-direction: row;
        gap: $measure--small4;
    }

    @include media('<tablet') {
        flex-direction: column;
    }
}

.courses-v26__floating-apply__link {
    @include cta-reset('\f061');

    border: $border-width-default $border-style-solid $color-purewhite;
    background: $color-brand-primary;
    color: $color-bg;
    @include anchor-default-outline($color-outline--dark);
    position: fixed;
    &:visited {
        color: $color-bg;
        border-color: $color-purewhite;
    }

    &:focus {
        background: $color-brand-primary;
        color: $color-bg;
    }

    &:active,
    &:focus {
        border-color: $color-brand-primary;
    }

    &:hover,
    &:active {
        @include media('hover') {
            border-color: $color-purewhite;
            background-image: none;
            background: $color-red70;
        }
    }
}

.courses-v26 {
    // Entry requirements dropdown filter styles

    .dropdown-filter {
        margin-top: 0;
    }

    .dropdown-filter__select {
        margin-top: 0;
        position: inherit;
        line-height: inherit;
        border: $border-width-hairline $border-style-solid $color-nearblack;
        height: $measure--medium4;
        padding: $measure--threequarters $measure--small4
            $measure--threequarters $measure--basic;
    }

    // Hide tab panel headins as not in design - we still need this for screen readers?
    .tabs__panel__heading {
        display: none;
    }

    // Employability section
    .courses-v26__employability {
        padding-bottom: $measure--medium3;
    }

    .courses-v26__employability__info-cards {
        display: flex;
        flex-direction: column;

        @include media('<small') {
            flex-direction: row;
            gap: $measure--small2;
        }

        @include media('<mobile') {
            flex-direction: column;
            gap: 0;
        }
    }
}

// Course v26 section 1/3 2/3 grid styles
.courses-v26 {
    .courses-v26__col {
        display: grid;
        @include content-grid();
        grid-column-gap: $measure--half;
    }

    .courses-v26__col--padding {
        // Standardise column top padding and reset spacing on each column's first child.
        .courses-v26__col-1-3,
        .courses-v26__col-2-3 {
            padding-top: $measure--small3;
            > :first-child {
                padding-top: 0;
                margin-top: 0;
            }
        }

        // Reset top spacing on the first child of a nested content wrapper.
        // Example: .courses-v26__col-1-3 > .courses-v26__col-content > h2
        .courses-v26__col-content {
            > :first-child {
                padding-top: 0;
                margin-top: 0;
            }
        }
    }

    .courses-v26__col-1-3 {
        grid-column: 1 / span 6;
        @include media('<small') {
            grid-column: 1 / -1;
        }
    }

    .courses-v26__col-2-3 {
        grid-column: 8 / span 12;
        @include media('<small') {
            grid-column: 1 / -1;
        }
    }
}

//How to apply section styles
.courses-v26 .courses-v26__apply {
    background: $color-zinc60;
    color: $color-purewhite;
    padding-top: $measure--medium3;
    padding-bottom: $measure--medium3;

    h2 {
        margin-top: 0;
    }

    .info-card-v26__wrapper {
        margin-left: 0;
        list-style-type: none;
        display: flex;
        flex-direction: row;
        max-width: initial;

        li {
            margin-right: $measure--small2;
            display: flex;

            &:last-of-type {
                margin-right: 0;
            }
        }
    }

    .courses-v26__apply--CTA {
        @include cta-primary-icon-dark-bg($color-purewhite, $color-nearblack);
        width: 100%;
        margin-bottom: $measure--basic;
        justify-content: center;

        &:hover,
        &:active {
            background: $color-brand-primary;
            border-color: $color-brand-primary;
        }
    }
}

// Related courses section
.courses-v26__related-courses {
    background: $color-gray3;
}

// Housing and student life section
.courses-v26__student-life {
    background: $color-zinc60;
    position: relative;
    color: $color-purewhite;
    overflow: hidden;
    padding-top: $measure--large4;

    @include media('<mobile') {
        padding-top: $measure--medium3;
    }

    .courses-v26__student-life__deco {
        position: absolute;
        height: $measure--huge5;
        top: -$measure--medium11;
        left: 50%;
        translate: -50% 0;
    }

    .section__content--wide {
        display: flex;
        flex-direction: column;
    }

    .courses-v26__student-life__anchors-block {
        max-width: 100%;
        text-align: center;
        margin-top: $measure--small1;
        margin-bottom: $measure--medium3;
        list-style: none;
        display: flex;
        flex-direction: row;
        justify-content: center;
        margin-left: 0;
        gap: $measure--small1;
        flex-wrap: balance;

        @include media('<mobile') {
            flex-direction: column;
        }
    }

    .courses-v26__student-life__anchor {
        color: $color-purewhite;
        @include anchor-inline(
            $color-purewhite,
            $color-purewhite,
            $color-nearblack,
            $color-purewhite
        );
    }
}

.courses-v26__student-life__heading {
    text-align: center;
}

.courses-v26__student-life__intro {
    align-self: center;
}

.courses-v26 {
    p,
    ol,
    ul {
        max-width: $max-line-length-65;
    }
}

// ul element width overrides for above...
.courses-v26 {
    .embla__container,
    .related-content,
    .related-courses,
    .nav-sticky__items {
        max-width: none;
    }
}
