.finder__results,
.search__results {
    .card--contact-v26 {
        @include search-contact-research-card();
    }
}

.card--contact-v26 {
    @include contact-research-card();
}

.card.card--contact-v26 {
    margin-top: 0;
    margin-bottom: 0;
    padding-bottom: $measure--small2;

    .card__details {
        figure {
            margin: 0;
        }

        picture {
            display: block;
            line-height: 0;
        }

        .card__details__text {
            padding-bottom: $measure--basic;
            padding: 0;
        }

        .card__image ~ .card__details__text {
            position: relative;
            top: -$measure--small4;
        }
    }

    .card__heading {
        display: block;
        width: 93%;
        margin-top: 0;
        background: $color-purewhite;
        padding: $measure--basic $measure--basic $measure--half $measure--basic;
    }

    .wrapper--card--contact-v26__content {
        background: $color-purewhite;
        overflow: hidden;
        padding: 0 $measure--basic $measure--basic $measure--basic;
    }

    .card__tag + .card__tag {
        margin-top: $measure--half;
    }
}

.card--contact-v26__content .icon {
    font-size: $font-size--gamma;
}
