// default dock height, override per instance with --sticky-cta-height.  JS will auto update based on actual button height
$sticky-cta-height: 50px !default;

.sticky-cta__dock {
    height: var(
        --sticky-cta-height,
        #{$sticky-cta-height}
    ); // matches the button height, so the space is always kept
    display: flex;
    justify-content: flex-end;
    align-items: center;
}

.sticky-cta {
    position: fixed;
    right: $measure--small4;
    bottom: $measure--small4;
    z-index: z-index('inpage');
    &.is-docked {
        z-index: z-index('default');
        position: static;
    }
}
