.info-cards {
    display: flex;
    gap: $measure--small2;

    &--column {
        flex-direction: column;
    }
}

.info-card-v26 {
    font-size: $measure--threequarters;
    position: relative;
    display: flex;
    align-items: flex-end;
    width: 100%;
    max-width: $measure--large2 * 3;
    aspect-ratio: 1 / 1;
    padding: $measure--small2;

    div:not(.embla__slide) > & + & {
        //margin-top: $measure--small4;
    }

    .courses-v26__col-1-3 &:first-child {
        // margin-top: $measure--small4;
    }

    &__theme__dark {
        color: $color-purewhite;
        background: $color-zinc60;
    }

    &__theme__light {
        color: $color-nearblack;
        background: $color-zinc30;
    }

    &__icon {
        position: absolute;
        top: $measure--small2;
        right: $measure--small2;
        font-size: $measure--small3;
    }

    &__content {
        * {
            @include smalltype();

            @include media('<desktop') {
                font-size: $measure--basic;
            }

            @include media('<mobile') {
                font-size: $font-size--smalltype;
            }
        }
    }

    &__text {
        font-weight: $font-weight-medium;
        margin-bottom: $measure--threequarters;
        @include font-family('heading');
        @include heading-font-features();
        @include thetatype();
        line-height: 1;
        font-weight: $font-weight-bold;
    }

    &__text-above {
        margin-top: 0;
        line-height: 1.2;
        margin-bottom: $measure--half;
        font-weight: $font-weight-bold;
    }

    &__text-below {
        margin: 0;
        line-height: 1.2;
    }
}
