.dropdown {
    height: $measure--medium4;
    font-weight: $font-weight-medium;

    @include font-family('default');
    @include body-font-features();
    @include alphatype();
    @include dropdown-filter-select(
        $color-gray7,
        $color-nearblack,
        $color-purewhite
    );
    line-height: 1;
    padding: $measure--threequarters $measure--small4 $measure--threequarters
        $measure--basic;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'><path fill='%23333' d='M297.4 438.6C309.9 451.1 330.2 451.1 342.7 438.6L502.7 278.6C515.2 266.1 515.2 245.8 502.7 233.3C490.2 220.8 469.9 220.8 457.4 233.3L320 370.7L182.6 233.4C170.1 220.9 149.8 220.9 137.3 233.4C124.8 245.9 124.8 266.2 137.3 278.7L297.3 438.7z'/></svg>"); //SVG value used from FA cheveron down
    background-repeat: no-repeat;
    background-position: right $measure--basic center;
    background-size: $measure--threequarters;
    appearance: none;
    min-width: 380px;
    &:focus {
        @include outline-properties();
    }
    & + & {
        margin-top: $measure--threequarters;
    }
    &--wide {
        width: 100%;
    }
    &--pill {
        border-radius: $border-radius-round;
    }
}

.dropdown__label {
    font-weight: $font-weight-medium;
}
.dropdown__wrapper {
    display: flex;

    gap: $measure--basic;
    align-items: center;
    margin-top: $measure--basic;
    @include media('<tablet') {
        flex-direction: column;
        align-items: flex-start;
    }
}
