.course {
    &__header {
        padding-top: $measure--small1; //Takes in account the padding/margin coming from section container
        width: 100%;
        h1 {
            font-weight: $font-weight-normal;
            margin-bottom: $measure--basic;
        }
    }

    &__year-select {
        display: flex;
        align-items: center;

        &-text {
            font-weight: $font-weight-bold;
            margin-right: $measure--threequarters;
        }
    }
}

.course-hero {
    display: grid;
    grid-template-areas:
        'left'
        'right'
        'bottom';
    grid-template-columns: 1fr;
    gap: $measure--small2;
    @include media('>=between') {
        grid-template-columns: 1fr 1fr;
        grid-template-areas:
            'left right'
            'bottom bottom';
    }

    &__links {
        display: flex;
        gap: $measure--threequarters;
    }
    &__link {
        @at-root #{&},
            article a#{&} {
            text-decoration: underline;
            text-decoration-thickness: $border-width-default;
            text-underline-offset: 0.2rem;
            line-height: 1.3;
            color: $color-purewhite;
            position: relative;
            margin-left: $measure--small3;
            border: none;

            @include anchor-hover-background($color-purewhite);

            &:before {
                color: $color-red50;
                font: var(--fa-font-regular);
                font-size: $measure--small1;
                content: fa-content($fa-var-circle-chevron-right);
                position: absolute;
                left: -$measure--small3;
            }

            &:visited {
                color: $color-purewhite;
                border: none;

                &:hover {
                    color: $color-nearblack;
                }
            }

            &:hover {
                text-decoration: underline;
                text-decoration-color: $color-purewhite;
                text-decoration-thickness: 0.125rem;
                border: none;
            }

            &:focus,
            &:active {
                border: none;
                outline-color: $color-purewhite; // visible on the dark hero
            }

            &:focus:not(:hover) {
                color: $color-purewhite;
            }

            &:active {
                // overrides article a:active's #006bbd. Match whatever
                // anchor-hover-background applies on hover.
                background-color: $color-purewhite;
                color: $color-nearblack;
            }
        }
    }
    &__left {
        display: flex;
        flex-direction: column;
        grid-area: left;
    }
    &__right {
        grid-area: right;
    }
    &__btm {
        grid-area: bottom;
    }
}

.keyinfo {
    &__grid {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: $measure--threequarters;
        margin-top: 0;
        max-width: none;
    }

    &__item {
        // font-size: $measure--threequarters;
        @include extrasmalltype();
        background-color: $color-purewhite;
        padding: $measure--small1;
        max-width: none;
        margin-top: 0;
        &-separator {
            color: $color-gray5;
        }
        &-heading,
        &-details {
            @include font-family('default');
            @include body-font-features();
            font-weight: $font-weight-normal;
            font-size: inherit;
        }

        &-heading {
            position: relative;
            &--icon {
                padding-left: $measure--small2;
                & > [class^='fa-'],
                & > [class*=' fa-'] {
                    color: $color-red50;
                    position: absolute;
                    left: 0;
                    top: 3px; //Shime to align icon with top of text
                    font-size: $measure--basic;
                }
            }
        }
        &-details {
            &.keyinfo__item-location {
                display: flex;
                align-items: center;

                .keyinfo__item-location__icon {
                    @include alphatype();
                    background-color: $color-red50;
                    display: inline-block;
                    height: $font-size--icon;
                    width: $measure--basic;
                    -webkit-mask: url('https://www.citystgeorges.ac.uk/__data/assets/file/0009/974304/fa-shape-ring.svg/_nocache')
                        no-repeat center / contain;
                    mask: url('https://www.citystgeorges.ac.uk/__data/assets/file/0009/974304/fa-shape-ring.svg/_nocache')
                        no-repeat center / contain;
                    margin-right: $measure--quarter;
                }
            }
        }
        dt {
            text-transform: uppercase;
        }

        &--full {
            grid-column: 1 / -1;
        }

        // &--icon {
        //     display: grid;
        //     grid-template-columns: $measure--basic 1fr;
        //     column-gap: $measure--half;
        //     &::before {
        //         font: var(--fa-font-regular);
        //         font-size: $measure--basic;
        //         content:fa-content($fa-var-circle);
        //     }
        //     dt, dd {
        //         grid-column: 2;
        //     }
        // }
    }
}

//Key info duration and UCAS code show depending on select option
.js {
    #key-info {
        .course-hero__left:has(select option[value='Full time']:checked)
            + .course-hero__right {
            .keyinfo__duration,
            .keyinfo__ucas-code,
            .keyinfo__item-separator {
                display: none;
            }
            .keyinfo__duration[data-study-mode='Full time'],
            .keyinfo__ucas-code[data-study-mode='Full time'] {
                display: block;
            }
        }

        .course-hero__left:has(select
                option[value='With Placement year']:checked)
            + .course-hero__right {
            .keyinfo__duration,
            .keyinfo__ucas-code,
            .keyinfo__item-separator {
                display: none;
            }
            .keyinfo__duration[data-study-mode='Placement year'],
            .keyinfo__ucas-code[data-study-mode='Placement year'] {
                display: block;
            }
        }

        .course-hero__left:has(select option[value='Study abroad']:checked)
            + .course-hero__right {
            .keyinfo__duration,
            .keyinfo__ucas-code,
            .keyinfo__item-separator {
                display: none;
            }
            .keyinfo__duration[data-study-mode='Study abroad'],
            .keyinfo__ucas-code[data-study-mode='Study abroad'] {
                display: block;
            }
        }
    }
}
